    if changed is not original and custody is not None:
        custody.callback(self.settle_unbound, tuple((key for key in changed.rows if key not in original.rows)))
    return changed

def bind_turn_input(self, keys: tuple[str, ...], *, admission: int, turn_id: str, native_id: str, text: str, already_bound: bool) -> bool:
    """Bind a turn's unresolved inputs to the native input carrying them.

        ``already_bound`` (a send-now re-send) requires the existing binding to match.
        """
    document = self.read(keys)
    for row in document.rows.values():
        row.require_not_cleared()
    if any((not document.lookup(key).unresolved or not document.lookup(key).matches_admission(admission) for key in keys)):
        return False
    if already_bound:
        return all((document.lookup(key).matches_native(native_id=native_id, turn_id=turn_id, text=text) for key in keys))
    return self.bind_originals(keys, admission=admission, turn_id=turn_id, native_id=native_id, text=text)

def wait_for(self, session: TurnSession) -> TurnWait:
    if session.awaiting_native_attestation:
        return self.preflight_wait
    if session.stats.requested:
        return self.poll_wait
    if session.admission.awaiting_start and (not self.phase.pauses_input_clock):
        return self.input_wait
    if session.active_tools:
        return self.unbounded_wait
    if self.phase.model_wait(self.model_wait.timeout()) is None:
        return self.unbounded_wait
    return self.model_wait

